posts.body:
Might be time to rein in your goals?
Like I said, you can get the "style" with minimal changes:
JavaScript:
(() => {

   const margin = 36

   // Disable menu bg filters
   const Scene_MenuBase_createBackground = Scene_MenuBase.prototype.createBackground;
   Scene_MenuBase.prototype.createBackground = function() {
       Scene_MenuBase_createBackground.apply(this)
       this._backgroundSprite.filters = [];
       this.setBackgroundOpacity(255);
   }

   // Flip command and status windows
   Scene_MenuBase.prototype.isRightInputMode = function() {
       return false;
   }

   // Cap the status window width
   const Scene_Menu_createStatusWindow = Scene_Menu.prototype.createStatusWindow;
   Scene_Menu.prototype.createStatusWindow = function() {
       Scene_Menu_createStatusWindow.apply(this)
       const width = this._statusWindow.width;
       this._statusWindow.width = width - margin;
       this._statusWindow.x += margin;
   }

   // Cap the command window height
   const Scene_Menu_createCommandWindow = Scene_Menu.prototype.createCommandWindow;
   Scene_Menu.prototype.createCommandWindow = function() {
       Scene_Menu_createCommandWindow.apply(this)
       const window = this._commandWindow;
       const maxHeight = window.height;
       const minHeight = this.calcWindowHeight(window.maxItems(), true)
       window.height = Math.min(minHeight, maxHeight)
   }

   // Disable command and menu item shading
   Window_MenuStatus.prototype.drawItemBackground = function(index) { };
   Window_MenuCommand.prototype.drawItemBackground = function(index) { };

})();
Overhauling the layout is inherently more time-consuming due to the hardcoded nature of MZ's UI.
You're welcome to use the above code and included window skin to get started, no credit required.
I'm not at my PC as I write this, and I've been writing WoW Classic addons for the past week, so I might've overlooked something with my code as my brain isn't in RPG Maker mode right now. But, I think you get the idea.
The font is
Nunito
which is a decent match for the Switch version of Dragon Quest 3 shown in your screenshots.
Good luck.
